<?php
declare(strict_types=1);
function modules(): array { return [
 'customers'=>['title'=>'Customers','singular'=>'customer','icon'=>'users','description'=>'Good relationships start with a clear picture.','fields'=>['name'=>['Full name','text',true],'company'=>['Company','text'],'email'=>['Email address','email'],'phone'=>['Phone number','tel'],'address'=>['Billing address','textarea'],'gstin'=>['GSTIN','text'],'notes'=>['Notes','textarea']]],
 'leads'=>['title'=>'Leads & Deals','singular'=>'lead','icon'=>'target-arrow','description'=>'Turn your next conversation into your next opportunity.','fields'=>['name'=>['Contact name','text',true],'company'=>['Company','text'],'email'=>['Email address','email'],'phone'=>['Phone number','tel'],'value'=>['Deal value (₹)','number',true],'stage'=>['Pipeline stage',['New','Qualified','Proposal','Negotiation','Won','Lost']],'source'=>['Lead source',['Website','Referral','Social media','Direct','Other']],'close_date'=>['Expected close','date'],'follow_up'=>['Follow-up date','date'],'assigned_to'=>['Assigned manager','users'],'notes'=>['Notes','textarea']]],
 'products'=>['title'=>'Products & Services','singular'=>'product','icon'=>'package','description'=>'Everything you sell, organized in one place.','fields'=>['name'=>['Name','text',true],'description'=>['Description','textarea'],'sku'=>['SKU / internal code','text'],'category'=>['Category',['Service','Product','Consulting','Subscription']],'unit'=>['Unit','text'],'price'=>['Selling price (₹)','number',true],'tax_rate'=>['Default tax rate (%)','number']]],
 'tasks'=>['title'=>'Tasks & Reminders','singular'=>'task','icon'=>'checkbox','description'=>'A little structure. A more productive day.','fields'=>['title'=>['Task title','text',true],'description'=>['Description','textarea'],'due_date'=>['Due date','date',true],'priority'=>['Priority',['Low','Medium','High']],'status'=>['Status',['Pending','In Progress','Completed','Cancelled']],'assigned_to'=>['Assigned manager','users'],'customer_id'=>['Related customer','customers']]],
 'expenses'=>['title'=>'Expenses','singular'=>'expense','icon'=>'receipt','description'=>'Know where your money goes, down to the last detail.','fields'=>['description'=>['Description','text',true],'category'=>['Category',['Software','Office','Travel','Marketing','Utilities','Professional fees','Other']],'amount'=>['Amount (₹)','number',true],'expense_date'=>['Expense date','date',true],'method'=>['Payment method',['Cash','Bank transfer','UPI','Card','Cheque','Other']],'vendor'=>['Vendor','text'],'reference'=>['Reference','text'],'notes'=>['Notes','textarea']]],
 ]; }
function validate_record(string $module,array $input): array {
    $def=modules()[$module]??throw new DomainException('Unknown module.'); $out=[];
    foreach($def['fields'] as $key=>$field) { [$label,$type]=$field; $value=trim((string)($input[$key]??'')); if(($field[2]??false)&&$value==='') throw new DomainException($label.' is required.'); if(mb_strlen($value)>($type==='textarea'?4000:200)) throw new DomainException($label.' is too long.'); if($type==='email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL)) throw new DomainException('Please enter a valid email address.'); if($type==='date') $value=$value===''?null:valid_date($value); if($type==='number') { $value=$value===''?'0':decimal(scaled($value)); if($key==='tax_rate'&&scaled($value)>10000) throw new DomainException('Tax rate cannot exceed 100%.'); if($key==='amount'&&scaled($value)===0) throw new DomainException('Expense must be greater than zero.'); } if(is_array($type)&&!in_array($value,$type,true)) throw new DomainException('Invalid '.$label.'.'); if(in_array($type,['users','customers'],true)) { if($value==='') $value=null; else { $table=$type; if(!one("SELECT id FROM $table WHERE id=? AND business_id=?",[(int)$value,bid()])) throw new DomainException('Invalid related record.'); $value=(int)$value; } } $out[$key]=$value; }
    if($module==='tasks') $out['completed_at']=$out['status']==='Completed'?date('Y-m-d H:i:s'):null;
    return $out;
}
function save_record(string $module,array $input,?int $id=null): int { require_permission($module.($id?'.edit':'.create')); $data=validate_record($module,$input); return transaction(function() use($module,$data,$id,$input){ if($id){ $record=one("SELECT * FROM $module WHERE id=? AND business_id=? FOR UPDATE",[$id,bid()]); if(!$record) throw new DomainException('Record not found.'); if((int)($input['version']??0)!==(int)$record['version']) throw new DomainException('This record changed since you opened it. Reload and try again.'); $sets=implode(',',array_map(fn($k)=>"$k=?",array_keys($data))); query("UPDATE $module SET $sets,version=version+1 WHERE id=? AND business_id=?",[...array_values($data),$id,bid()]); } else { $columns=implode(',',array_keys($data)); $marks=implode(',',array_fill(0,count($data)+1,'?')); query("INSERT INTO $module (business_id,$columns) VALUES ($marks)",[bid(),...array_values($data)]); $id=(int)db()->lastInsertId(); } audit($module.'.'.(isset($record)?'updated':'created'),$module,$id); return $id; }); }
function archive_record(string $module,int $id): void { require_permission($module.'.archive'); if(!isset(modules()[$module])) throw new DomainException('Unknown module.'); query("UPDATE $module SET status='Archived',version=version+1 WHERE id=? AND business_id=?",[$id,bid()]); audit($module.'.archived',$module,$id); }
function financial_summary(string $start,string $end): array {
    $b=bid(); $revenue=scalar("SELECT COALESCE(SUM(total),0) FROM documents WHERE business_id=? AND type='invoice' AND status='Issued' AND issue_date BETWEEN ? AND ?",[$b,$start,$end]);
    $cash=scalar('SELECT COALESCE(SUM(amount),0) FROM payments WHERE business_id=? AND reversed_at IS NULL AND payment_date BETWEEN ? AND ?',[$b,$start,$end]);
    $expenses=scalar("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE business_id=? AND status='Active' AND expense_date BETWEEN ? AND ?",[$b,$start,$end]);
    $out=one("SELECT COALESCE(SUM(d.total-COALESCE(p.paid,0)),0) outstanding, COALESCE(SUM(CASE WHEN d.due_date<CURRENT_DATE THEN d.total-COALESCE(p.paid,0) ELSE 0 END),0) overdue,COUNT(*) count FROM documents d LEFT JOIN (SELECT document_id,SUM(amount) paid FROM payments WHERE business_id=? AND reversed_at IS NULL GROUP BY document_id) p ON p.document_id=d.id WHERE d.business_id=? AND d.type='invoice' AND d.status='Issued' AND d.issue_date BETWEEN ? AND ?",[$b,$b,$start,$end]);
    return ['revenue'=>$revenue,'cash'=>$cash,'expenses'=>$expenses,'net'=>(float)$cash-(float)$expenses]+$out;
}
function document_list_sql(string $type,string $search='',?array $dates=null,string $status=''): array {
    $sql="SELECT d.*,c.name customer_name,c.company,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.document_id=d.id AND p.business_id=d.business_id AND p.reversed_at IS NULL) paid FROM documents d JOIN customers c ON c.id=d.customer_id AND c.business_id=d.business_id WHERE d.business_id=? AND d.type=?";
    $params=[bid(),$type];if($search!==''){$sql.=' AND (d.number LIKE ? OR c.name LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}if($dates){$sql.=' AND d.issue_date BETWEEN ? AND ?';$params=[...$params,...$dates];}
    $sql="SELECT source.*,CASE WHEN type='quotation' THEN status WHEN status IN ('Draft','Void') THEN status WHEN paid>=total THEN 'Paid' WHEN paid>0 THEN 'Partially Paid' WHEN due_date<CURRENT_DATE THEN 'Overdue' ELSE 'Issued' END derived_status FROM ($sql) source";
    if($status!==''){$sql="SELECT * FROM ($sql) filtered WHERE derived_status=?";$params[]=$status;}return [$sql,$params];
}
function list_documents(string $type,string $search='',int $limit=10,int $offset=0,?array $dates=null,string $status=''): array {[$sql,$params]=document_list_sql($type,$search,$dates,$status);return rows($sql.' ORDER BY issue_date DESC,id DESC LIMIT '.max(1,min(100,$limit)).' OFFSET '.max(0,$offset),$params);}
function count_documents(string $type,string $search='',?array $dates=null,string $status=''): int {[$sql,$params]=document_list_sql($type,$search,$dates,$status);return (int)scalar("SELECT COUNT(*) FROM ($sql) counted",$params);}
